// Only generated bytes and short-lived identities; signaling stays on loopback.
import assert from 'node:assert/strict';
import { createHash, randomBytes } from 'node:crypto';
import fs from 'node:fs/promises';
import { createServer } from 'node:http';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';
import os from 'node:os';
import path from 'node:path';
import wrtc from '@roamhq/wrtc';
import Socket from 'ws';
import SignalingServer from '../../server/signaling-server.js';
import { createSigningIdentity } from '../../packages/reploid/src/artifacts/identity.js';
import { createNativeParticipant } from '../../server/native-participant-runtime.js';
import { createNativeRtcAdapter } from '../../server/native-rtc-adapter.js';
import catalog from '../../shared/config/chat-models.json' with { type: 'json' };
import { runPrefill } from './prefill-private-stage.mjs';

const hash = b => createHash('sha256').update(b).digest('hex');
const root = await fs.mkdtemp(path.join(os.tmpdir(), 'synthetic-private-stage-'));
const directory = key => path.join(root, key);
const sourceDir = directory('source'), target = directory('stage'), cache = directory('cache');
const identities = await Promise.all([0,1,2].map(() => createSigningIdentity({ algorithm: 'Ed25519' })));
const [receiver, supplier, stranger] = identities, roomToken = randomBytes(32).toString('hex');
const roomId = 'reploid-swarm-stage-' + randomBytes(10).toString('hex');
const signaling = new SignalingServer({ path:'/signaling', accessToken: roomToken });
const server = createServer((req,res) => { res.writeHead(404).end(); });
server.on('upgrade',(req,socket,head) => signaling.handleUpgrade(req,socket,head));
const checks = [];
let peer, gpuOpens = 0;
try {
  await Promise.all([sourceDir,target].map(name => fs.mkdir(name)));
  await fs.writeFile(directory('identity.json'), JSON.stringify(receiver), {mode:0o600});
  await fs.writeFile(directory('room-token'), roomToken, {mode:0o600});
  server.listen(0,'127.0.0.1'); await once(server,'listening');
  const signalingUrl = 'ws://127.0.0.1:' + server.address().port + '/signaling';
  const chunks = [Buffer.from('aaaa'),Buffer.from('bbbb'),Buffer.from('cccc')], shard = Buffer.concat(chunks);
  const fixtureId = 'tiny-stage-prefill';
  const manifest = Buffer.from(JSON.stringify({ modelId: fixtureId, hashAlgorithm:'sha256',
    shards:[{ index:0, filename:'weights.bin', size:shard.length, hash:hash(shard) }] }));
  const pieces = chunks.map((b,i) => ({size:b.length,offset:i*b.length,identity:'sha256:'+hash(b)}));
  const index = Buffer.from(JSON.stringify({schema:'doppler.verified-pieces/v1',manifestIdentity:'sha256:'+hash(manifest),
    maxPieceBytes:4,files:[{path:'weights.bin',size:shard.length,pieces}]}));
  for (const folder of [sourceDir,target]) {
    await fs.writeFile(path.join(folder,'manifest.json'),manifest);
    await fs.writeFile(path.join(folder,'index.json'),index);
  }
  await fs.writeFile(path.join(sourceDir,'weights.bin'),shard);
  const original = catalog.find(m => m.partitionPlan);
  const model = {...original,id:fixtureId,identity:'sha256:'+hash(manifest),
    partitionPlan:{...original.partitionPlan,modelId:fixtureId},source:{files:[
      {path:'manifest.json',role:'model-manifest',hashAlgorithm:'sha256',hash:hash(manifest),sizeBytes:manifest.length},
      {path:'index.json',role:'model-piece-index',hashAlgorithm:'sha256',hash:hash(index),sizeBytes:index.length}
    ]}};
  const stages = [[0,1],[2]].map((which,stageIndex) => ({stageIndex,layerRange:model.partitionPlan.partitions[stageIndex].layerRange,
    assignedBytes:4*which.length,ranges:which.map(i=>({...pieces[i],shardIndex:0,path:'weights.bin'}))}));
  const inventory = Buffer.from(JSON.stringify({modelId:model.id,modelIdentity:model.identity,planId:model.partitionPlanId,indexSha256:hash(index),stages}));
  const inventoryFile=directory('inventory.json'); await fs.writeFile(inventoryFile,inventory);
  const config = {enrollmentStatus:'enrolled',modelId:model.id,modelIdentity:model.identity,planId:model.partitionPlanId,stageIndex:0,inventorySha256:hash(inventory),
    supplierPublicJwk:supplier.publicJwk,supplierId:supplier.peerId,identityFile:directory('identity.json'),roomTokenFile:directory('room-token'),
    roomId,signalingUrl,modelDirectory:target,cacheDirectory:cache,maxCacheBytes:30000,maxDownloadBytes:16,offerTimeoutMs:8000,hostIceOnly:true};
  const run = (settings, transfer, signal, onProgress) => runPrefill(settings,inventoryFile,transfer,signal,{models:[model],onProgress});
  const deadline = () => AbortSignal.timeout(29000);
  assert.equal((await run(config,false,deadline())).mode,'plan');
  await assert.rejects(run({...config,enrollmentStatus:'offline-unenrolled'},true,deadline()),/cannot transfer/);
  await assert.rejects(fs.stat(cache), {code:'ENOENT'}); checks.push('plan-no-cache-or-network');
  await assert.rejects(run({...config,inventorySha256:'0'.repeat(64)},true,deadline()),/separately pinned/);
  await assert.rejects(run({...config,maxCacheBytes:4},true,deadline()),/cache budget/); checks.push('pins-and-budget-preflight');
  class HostSocket extends Socket { constructor(url) { super(url,{origin:'http://localhost:8000'}); } }
  peer = await createNativeParticipant({model,modelDirectory:sourceDir,cacheDirectory:directory('supplier-cache'),identity:supplier,
    nativeGpu:()=>{gpuOpens++;throw Error('Unexpected GPU access');},rtc:createNativeRtcAdapter(wrtc),WebSocket:HostSocket,
    signalingUrl,roomId,roomToken,getRtcConfig:()=>({iceServers:[]}),maxSupplyBytes:128,executionMode:'whole-model'});
  await peer.shareFiles(true);
  const ticker = setInterval(()=>peer.announceFiles(),150);
  try {
    const rejectConfig = {...config,supplierPublicJwk:stranger.publicJwk,supplierId:stranger.peerId};
    const suppliedBefore = peer.getFileState().suppliedBytes;
    await assert.rejects(run(rejectConfig,true,deadline()), error =>
      error.errors?.some(source => /peer identity is not authorized/.test(source.message)));
    assert.equal(peer.getFileState().suppliedBytes, suppliedBefore);
    const lock = new DatabaseSync(cache + '.stage-prefill.sqlite');
    try {
      lock.exec('BEGIN EXCLUSIVE');
      await assert.rejects(run(config,true,deadline()), /locked/);
    } finally { lock.close(); }
    checks.push('simultaneous-prefillers-excluded');
    assert(!(await fs.readdir(cache)).includes('sha256-'+hash(chunks[0]))); checks.push('unapproved-signed-supplier-no-payload');
    const controller = new AbortController();
    await assert.rejects(run(config,true,AbortSignal.any([deadline(),controller.signal]), state => {
      if (state.pieces===1) controller.abort(new Error('controlled interruption'));
    }), /controlled interruption/);
    const stored = i => path.join(cache,'sha256-'+hash(chunks[i]));
    assert.deepEqual(await fs.readFile(stored(0)),chunks[0]); await assert.rejects(fs.stat(stored(1)),{code:'ENOENT'});
    checks.push('interrupted-only-first-piece-committed');
    // A crash can leave incomplete temporary bytes. Only canonical verified names are reusable.
    const partial = stored(1) + '.prior.tmp';
    await fs.writeFile(partial, chunks[1].subarray(0,2));
    const recovered = await run(config,true,deadline());
    assert.deepEqual(await fs.readFile(partial), chunks[1].subarray(0,2));
    assert.equal(recovered.pieces,2); assert.equal(recovered.reusedBytes,4); assert.equal(recovered.transferredBytes,4);
    assert.equal(recovered.reservedBefore,4); assert.equal(recovered.reservedAfter,8);
    await assert.rejects(fs.stat(stored(2)),{code:'ENOENT'}); checks.push('signed-peer-resume-and-unassigned-exclusion');
    assert.equal((await run(config,true,deadline())).reservedAfter,8); checks.push('repeat-charged-zero');
    await fs.writeFile(stored(1),'bad!');
    const repair = await run(config,true,deadline()); assert.equal(repair.reservedAfter,12);
    assert.deepEqual(await fs.readFile(stored(1)),chunks[1]); assert((await fs.readdir(cache)).some(n=>n.includes('.corrupt.')));
    checks.push('corruption-quarantined-and-repaired');
    await assert.rejects(run({...config,maxDownloadBytes:17},true,deadline()), /allowance changed/);
    checks.push('restart-cannot-renew-byte-budget');
    await fs.writeFile(stored(1),'oops');
    assert.equal((await run(config,true,deadline())).reservedAfter,16);
    await fs.writeFile(stored(1),'oops');
    await assert.rejects(run(config,true,deadline()), error =>
      error.errors?.some(source => source.code === 'CUSTODY_BUDGET_LIMIT'));
    await assert.rejects(fs.stat(stored(1)),{code:'ENOENT'});
    checks.push('exhausted-budget-no-new-payload');
    assert.equal(gpuOpens,0); console.log(JSON.stringify({checks,completed:recovered.pieces,assignedBytes:recovered.bytes,
      afterInterruption:recovered.reservedBefore,afterRecovery:recovered.reservedAfter,afterRepair:repair.reservedAfter,gpuOpens}));
  } finally { clearInterval(ticker); }
} finally {
  try { await peer?.close(); } finally { signaling.close(); server.close(); await fs.rm(root,{recursive:true,force:true}); }
}
